def f(g):
    cells=[(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v]
    rmax=max(r for r,c,v in cells)
    out=[[0]*len(g[0]) for _ in g]
    for r,c,v in cells:
        c2=c-(rmax-r)
        if 0<=c2<len(g[0]): out[r][c2]=v
    return out
